declarations.statement:
∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v},
  Auths.Rich.delegates parent grantId grant child → Auths.Rich.structuralScopeLe child.scope parent.scope

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v},
  Auths.Rich.delegates parent grantId grant child → child.root = parent.root

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v},
  Auths.Rich.delegates parent grantId grant child → child.subject = grant.subject ∧ child.lastGrant = some grantId

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v},
  Auths.Rich.delegates parent grantId grant child → child.remainingDepth < parent.remainingDepth

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v},
  Auths.Rich.delegates parent grantId grant child → Auths.Rich.structuralScopeLe child.scope parent.scope

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent child : Auths.Rich.ChainState v}
  {grantId : Auths.Rich.GrantId v} {grant : Auths.Rich.Grant v} {action : Auths.Rich.Action v}
  {expression : Auths.Rich.BudgetExpression},
  Auths.Rich.delegates parent grantId grant child →
    Auths.Rich.actionCovers child.scope action expression → Auths.Rich.actionCovers parent.scope action expression

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent : Auths.Rich.ChainState v}
  {grant : Auths.Rich.Grant v} (certified : Auths.Rich.CertifiedProjection parent grant),
  ¬Auths.Rich.extensionsLe (some grant.extensions) parent.scope.extensions → certified.value.extensionsAttenuate = false

∀ {v : Auths.Rich.Vocabulary} [inst : Auths.Rich.ExtensionLaws v] {parent : Auths.Rich.ChainState v}
  {grant : Auths.Rich.Grant v} (certified : Auths.Rich.CertifiedProjection parent grant),
  ¬Auths.Rich.rootPreserved parent grant → certified.value.rootPreserved = false

